package fr.proutlost.worldprep.snapshot;
import java.util.ArrayList;import java.util.HashSet;import java.util.List;import java.util.Set;
/** Chunk-streamable exact before-value journal. First write wins so rollback restores pre-apply state. */
public final class ChangeJournal<T>{public record Position(int x,int y,int z){}public record Change<T>(Position position,T before){}private final List<Change<T>> changes=new ArrayList<>();private final Set<Position> recorded=new HashSet<>();private boolean sealed;public void record(Position p,T before){if(sealed)throw new IllegalStateException("sealed");if(recorded.add(p))changes.add(new Change<>(p,before));}public void seal(){sealed=true;}public boolean sealed(){return sealed;}public int size(){return changes.size();}public List<Change<T>> reverse(){if(!sealed)throw new IllegalStateException("Snapshot must be sealed before rollback");var out=new ArrayList<>(changes);java.util.Collections.reverse(out);return List.copyOf(out);}public int integrityHash(){return changes.hashCode();}}
